function numOp(o) {
  return arrOp(Object.assign({ shape: "num", topic: "整数与数论", tags: ["整数", "循环", "数学"], hint: "注意使用 long long / 大整数，避免溢出。", cfg: { lo: 1, hi: 100 } }, o));
}
